/**
 * Resolve the English half of a bilingual "Hebrew | English" catalog name,
 * trimmed. Falls back to the whole (trimmed) string when there is no separator.
 */
const englishOf = (name: string): string => {
  const idx = name.lastIndexOf('|');
  return (idx >= 0 ? name.slice(idx + 1) : name).trim();
};

/**
 * Full CDN URLs of the public-domain demonstration images for an exercise, or
 * an empty array when the exercise is unmapped. Accepts either the bilingual
 * catalog name or a bare English name.
 */
export function getExerciseImages(name?: string | null): string[] {
  if (!name) return [];
  const paths = EXERCISE_IMAGE_PATHS[englishOf(name)];
  if (!paths) return [];
  return paths.map((p) => `${CDN_BASE}/${p}`);
}

/** The primary (start-position) demonstration image URL, or undefined if none. */
export function getExerciseImage(name?: string | null): string | undefined {
  return getExerciseImages(name)[0];
}
